namespace ghidra.framework.main;




using docking.action;
using ghidra.framework.data;
using ghidra.framework.main.datatable;
using ghidra.framework.main.datatable;
using ghidra.framework.main.datatree;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.framework.protocol.ghidra;
using ghidra.util;
using ghidra.util;

public class ProjectDataFollowLinkAction : FrontendProjectTreeAction {

	private FrontEndPlugin plugin;

	public ProjectDataFollowLinkAction(FrontEndPlugin plugin, string group) : base("Follow Link", plugin.getName())
    {
		this.plugin = plugin;
		setPopupMenuData(new MenuData(new string[] { "Follow Link" }, group));
		setHelpLocation(new HelpLocation("FrontEndPlugin", "Follow_Link"));
	}

	/* @Override */
	protected void actionPerformed(ProjectDataContext context) {

		List<DomainFile> selectedFiles = context.getSelectedFiles();
		if (selectedFiles.size() != 1) {
			return;
		}
		DomainFile file = selectedFiles.get(0);
		if (!file.isLink()) {
			return;
		}

		// Folder link may refer to another folder link
		string linkPath;
		try {
			linkPath = LinkHandler.getAbsoluteLinkPath(file);
			if (linkPath == null) {
				Msg.showError(this, context.getComponent(), "Invalid Link",
					"Link-file failed to provide link path: " + file);
				return;
			}
		}
		catch (IOException e) {
			Msg.showError(this, context.getComponent(), "Invalid Link", e.getMessage());
			return;
		}

		bool isFolderLink = file.getLinkInfo().isFolderLink();
		if (GhidraURL.isGhidraURL(linkPath)) {
			// Follow URL using a project view
			try {
				plugin.showInViewedProject(GhidraURL.toURL(linkPath), isFolderLink);
				return;
			}
			catch (IllegalArgumentException e) {
				Msg.error(this, "Invalid link URL: " + e.getMessage());
				return;
			}
		}

		// Check internal link
		ProjectData projectData = context.getProjectData();
		bool isFolder = isFolderLink && projectData.getFolder(linkPath) != null;
		if (!isFolder) {
			DomainFile referencedFile = projectData.getFile(linkPath);
			if (referencedFile == null) {
				// referenced folder or file not found
				return;
			}
		}

		// Path is local to its project data tree
		plugin.showInProjectTree(context.getProjectData(), linkPath, isFolder);
	}

	/* @Override */
	protected bool isEnabledForContext(ProjectDataContext context) {
		if (!(context.getComponent() is DataTree)) {
			return false;
		}
		if (context.getFolderCount() != 0 || context.getFileCount() != 1) {
			return false;
		}
		DomainFile file = context.getSelectedFiles().get(0);
		return file.isLink();
	}
}
